# ================= writer =================
import collections
BATCHES = json.load(open(os.path.join(BASE, "batches.json")))
WANT = {b: BATCHES[b] for b in ("B13", "B14", "B15")}
ALL = [c for b in ("B13","B14","B15") for c in WANT[b]]
assert len(ALL) == 60, len(ALL)
by_id = {}
for e in DATA:
    assert e[0] not in by_id, e[0]
    by_id[e[0]] = e
assert set(by_id) == set(ALL), (set(ALL) ^ set(by_id))

trig_count = collections.Counter()
for b in ("B13","B14","B15"):
    ids = WANT[b]
    assert len(ids) == 20
    for cid in ids:
        _, pred, basis, conf, trig = by_id[cid]
        cm, ru, di, reason = trig
        assert isinstance(pred, str) and pred.strip()
        assert isinstance(basis, str) and basis.strip()
        assert isinstance(conf, float) and 0.0 <= conf <= 1.0, (cid, conf)
        assert isinstance(cm, bool) and isinstance(ru, bool) and isinstance(di, bool)
        assert isinstance(reason, str)
        if not (cm or ru or di):
            assert reason == "", (cid, reason)
        obj = {"case_id": cid, "prediction_text": pred, "basis": basis,
               "confidence": conf,
               "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}}
        assert set(obj) == {"case_id","prediction_text","basis","confidence","trigger"}
        assert set(obj["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        trig_count["changed_main"] += cm; trig_count["reserve_used"] += ru; trig_count["disputed"] += di
    print(b, "written", len(ids))
print("total", len(by_id), "triggers", dict(trig_count))
for cid in ("LY-426","LY-501","LY-536"):
    p = os.path.join(OUT, cid + ".json")
    print(cid, os.path.getsize(p))
